SELECT emp17_pay_request_appr_id AS pay_request_appr_id
     , apr01_status_cd           AS pay_request_appr_status_code
     , f_cdnm('AprStatusCode', apr01_status_cd, emp17_company_id, apr01_reg_date) AS pay_request_appr_status_name
  FROM emp17_benefit
       LEFT OUTER JOIN apr01_appr b ON emp17_pay_request_appr_id = apr01_appr_id
 WHERE emp17_company_id = #{companyId}
   AND emp17_pay_request_yyyymm = #{yyyymm}
   AND emp17_benefit_cd LIKE #{benefitCode}
 LIMIT 1

SELECT 
     , NULL AS account_name
  FROM emp17_benefit
       LEFT OUTER JOIN apr01_appr ON emp17_appr_id = apr01_appr_id
 WHERE emp17_company_id = #{companyId}
   AND emp17_benefit_id = #{benefitId}

