 WHERE emp17_company_id = #{companyId}
   AND emp17_benefit_id IN
#{id}

UPDATE emp17_benefit
   SET emp17_benefit_yn = #{benefitYn}
 WHERE emp17_company_id = #{companyId}
   AND emp17_benefit_id IN
#{id}

UPDATE emp17_benefit
   SET emp17_note = #{note}
 WHERE emp17_company_id = #{companyId}
   AND emp17_benefit_id = #{benefitId}

UPDATE emp17_benefit
   SET emp17_appr_id = null
 WHERE emp17_benefit_id = #{benefitId}
   AND emp17_company_id = #{companyId}

